import {
  BOTTOM_POSITION,
  XYChartAxisProps,
  XYChartVisibleAxesConfig,
} from '../types/xy-chart.js';

export function getVisibleAxes(axes: XYChartAxisProps[]) {
  const bottomAxis = axes.find(
    (axis) => axis.position === BOTTOM_POSITION && !axis.hidden,
  );

  const visibleAxes: XYChartVisibleAxesConfig = {
    bottom: bottomAxis,
  };

  return visibleAxes;
}
